package com.fathom.transaction; import com.fathom.common.BaseEntity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="transactions") public class Transaction extends BaseEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="account_id",nullable=false) private UUID accountId; @Column(name="category_id") private UUID categoryId; @Column(name="transaction_date",nullable=false) private LocalDate transactionDate; @Column(nullable=false,precision=19,scale=4) private BigDecimal amount; @Enumerated(EnumType.STRING) @Column(nullable=false) private Direction direction; @Enumerated(EnumType.STRING) @Column(name="transaction_type",nullable=false) private TransactionType transactionType; @Enumerated(EnumType.STRING) @Column(nullable=false) private TransactionSource source; @Column(name="raw_description",columnDefinition="TEXT") private String rawDescription; private String merchant; @Column(columnDefinition="TEXT") private String notes; @Column(name="internal_transfer",nullable=false) private boolean internalTransfer=false; @Column(name="investment_transfer",nullable=false) private boolean investmentTransfer=false; @Column(name="debt_payment",nullable=false) private boolean debtPayment=false; @Column(name="linked_transaction_id") private UUID linkedTransactionId; @Column(name="import_hash") private String importHash; @PrePersist void init(){if(id==null)id=UUID.randomUUID();}
public UUID getId(){return id;} public UUID getUserId(){return userId;} public UUID getAccountId(){return accountId;} public UUID getCategoryId(){return categoryId;} public LocalDate getTransactionDate(){return transactionDate;} public BigDecimal getAmount(){return amount;} public Direction getDirection(){return direction;} public TransactionType getTransactionType(){return transactionType;} public TransactionSource getSource(){return source;} public String getRawDescription(){return rawDescription;} public String getMerchant(){return merchant;} public String getNotes(){return notes;} public boolean isInternalTransfer(){return internalTransfer;} public boolean isInvestmentTransfer(){return investmentTransfer;} public boolean isDebtPayment(){return debtPayment;} public UUID getLinkedTransactionId(){return linkedTransactionId;} public String getImportHash(){return importHash;} public void setUserId(UUID v){userId=v;} public void setAccountId(UUID v){accountId=v;} public void setCategoryId(UUID v){categoryId=v;} public void setTransactionDate(LocalDate v){transactionDate=v;} public void setAmount(BigDecimal v){amount=v;} public void setDirection(Direction v){direction=v;} public void setTransactionType(TransactionType v){transactionType=v;} public void setSource(TransactionSource v){source=v;} public void setRawDescription(String v){rawDescription=v;} public void setMerchant(String v){merchant=v;} public void setNotes(String v){notes=v;} public void setInternalTransfer(boolean v){internalTransfer=v;} public void setInvestmentTransfer(boolean v){investmentTransfer=v;} public void setDebtPayment(boolean v){debtPayment=v;} public void setLinkedTransactionId(UUID v){linkedTransactionId=v;} public void setImportHash(String v){importHash=v;} }
